+++ b/workspace/Verdesakay-Inventory-System/work/sqlite-startup/frontend-delay-before-retained-source.ts
@@ -133,6 +133,15 @@ describe('mobile bootstrap', () => {
     // hops through api.js's async request() + boot()'s .catch) — flush a real macrotask
     // so it's landed before we drive the router.
     await new Promise((r) => setTimeout(r, 0));
+    // Disposable diagnostic only: preserve the real IndexedDB operation, delay its acknowledgement.
+    const actualSave = win.mProductionDrafts.save;
+    win.mProductionDrafts.save = async (...args: any[]) => {
+      const value = await actualSave(...args);
+      fs.appendFileSync("/workspace/Verdesakay-Inventory-System/work/sqlite-startup/frontend-delay-before-retained.jsonl", JSON.stringify({ event: 'committed', at: Date.now(), kind: args[0]?.operation?.kind, state: args[0]?.operation?.state }) + '\n');
+      await new Promise(resolve => setTimeout(resolve, 250));
+      fs.appendFileSync("/workspace/Verdesakay-Inventory-System/work/sqlite-startup/frontend-delay-before-retained.jsonl", JSON.stringify({ event: 'acknowledged', at: Date.now(), kind: args[0]?.operation?.kind, state: args[0]?.operation?.state }) + '\n');
+      return value;
+    };
     return win;
   }
